def largest_palindrome(A, n):
    """Write a function to find the largest palindromic number in the given array.

    Only the first ``n`` elements of ``A`` are considered. A number is
    palindromic when its decimal representation reads the same forwards
    and backwards, so negative numbers and numbers ending in zero
    (other than zero itself) are not palindromes. Returns ``-1`` if no
    palindromic number is found.
    """
    if not A:
        return -1
    limit = len(A) if n is None else max(0, min(n, len(A)))
    best = None
    best_key = None
    for num in A[:limit]:
        text = str(num)
        if text != text[::-1]:
            continue
        try:
            key = int(text)
        except ValueError:
            try:
                key = float(text)
            except ValueError:
                key = text
        if best_key is None or key > best_key:
            best = num
            best_key = key
    return best if best is not None else -1
